74	    async fn list(
75	        &self,
76	        request: ListMemoriesRequest,
77	    ) -> Result<ListMemoriesResponse, MemoriesBackendError> {
78	        let max_results = request.max_results.min(MAX_LIST_RESULTS);
79	        let start = self.resolve_scoped_path(request.path.as_deref())?;
80	        let start_index = match request.cursor.as_deref() {
81	            Some(cursor) => cursor.parse::<usize>().map_err(|_| {
82	                MemoriesBackendError::invalid_cursor(cursor, "must be a non-negative integer")
83	            })?,
84	            None => 0,
85	        };
86	        let Some(metadata) = Self::metadata_or_none(&start).await? else {
87	            return Ok(ListMemoriesResponse {
88	                path: request.path,
89	                entries: Vec::new(),
90	                next_cursor: None,
91	                truncated: false,
92	            });
93	        };
94	        reject_symlink(&display_relative_path(&self.root, &start), &metadata)?;
95	
96	        let mut entries = if metadata.is_file() {
97	            vec![MemoryEntry {
98	                path: display_relative_path(&self.root, &start),
99	                entry_type: MemoryEntryType::File,
100	            }]
101	        } else if metadata.is_dir() {
102	            let mut entries = Vec::new();
103	            for path in read_sorted_dir_paths(&start).await? {
104	                let Some(metadata) = Self::metadata_or_none(&path).await? else {
105	                    continue;
106	                };
107	                if metadata.file_type().is_symlink() {
108	                    continue;
109	                }
110	
111	                let entry_type = if metadata.is_dir() {
112	                    MemoryEntryType::Directory
113	                } else if metadata.is_file() {
114	                    MemoryEntryType::File
115	                } else {
116	                    continue;
117	                };
118	                entries.push(MemoryEntry {
119	                    path: display_relative_path(&self.root, &path),
120	                    entry_type,
121	                });
122	            }
123	            entries
124	        } else {
125	            Vec::new()
126	        };
127	        if start_index > entries.len() {
128	            return Err(MemoriesBackendError::invalid_cursor(
129	                start_index.to_string(),
130	                "exceeds result count",
131	            ));
132	        }
133	
134	        let end_index = start_index.saturating_add(max_results).min(entries.len());
135	        let next_cursor = (end_index < entries.len()).then(|| end_index.to_string());
136	        let truncated = next_cursor.is_some();
137	        Ok(ListMemoriesResponse {
138	            path: request.path,
139	            entries: entries.drain(start_index..end_index).collect(),
140	            next_cursor,
141	            truncated,
142	        })
143	    }
